#include "lapislazuli/css/css_engine.hpp"
#include <algorithm>
#include <cctype>
#include <tuple>
namespace lapislazuli::css {
namespace {
bool ws(char c){return std::isspace(static_cast<unsigned char>(c))!=0;}
bool nameStart(char c){auto u=static_cast<unsigned char>(c);return std::isalpha(u)!=0||c=='_'||u>=128;}
bool nameChar(char c){auto u=static_cast<unsigned char>(c);return std::isalnum(u)!=0||c=='_'||c=='-'||u>=128;}
std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return char(std::tolower(c));});return s;}
std::string trim(std::string s){auto a=std::find_if_not(s.begin(),s.end(),ws);auto b=std::find_if_not(s.rbegin(),s.rend(),ws).base();return a>=b?std::string{}:std::string(a,b);}
bool hasClass(const dom::Element&e,std::string_view wanted){auto*v=e.getAttribute("class");if(!v)return false;std::size_t p=0;while(p<v->size()){while(p<v->size()&&ws((*v)[p]))++p;auto b=p;while(p<v->size()&&!ws((*v)[p]))++p;if(p>b&&std::string_view(*v).substr(b,p-b)==wanted)return true;}return false;}
bool simpleMatch(const SimpleSelector&s,const dom::Element&e){if(!s.tag.empty()&&s.tag!="*"&&s.tag!=e.name())return false;if(!s.id.empty()){auto*v=e.getAttribute("id");if(!v||*v!=s.id)return false;}for(auto&c:s.classes)if(!hasClass(e,c))return false;return true;}
bool matchAt(const Selector&s,std::size_t i,const dom::Element&e){if(!simpleMatch(s.parts[i],e))return false;if(i==0)return true;auto*p=e.parent();if(s.combinators[i-1]==Combinator::Child){return p&&p->type()==dom::NodeType::Element&&matchAt(s,i-1,static_cast<const dom::Element&>(*p));}while(p){if(p->type()==dom::NodeType::Element&&matchAt(s,i-1,static_cast<const dom::Element&>(*p)))return true;p=p->parent();}return false;}
std::vector<Declaration> declarations(const std::vector<Token>&t,std::size_t p,std::size_t end){std::vector<Declaration>out;while(p<end){while(p<end&&(t[p].type==TokenType::Whitespace||t[p].type==TokenType::Semicolon))++p;if(p>=end)break;if(t[p].type!=TokenType::Ident){while(p<end&&t[p].type!=TokenType::Semicolon)++p;continue;}auto prop=lower(t[p++].text);while(p<end&&t[p].type==TokenType::Whitespace)++p;if(p>=end||t[p].type!=TokenType::Colon){while(p<end&&t[p].type!=TokenType::Semicolon)++p;continue;}++p;std::string value;int depth=0;while(p<end){auto k=t[p].type;if(k==TokenType::OpenBrace)++depth;if(k==TokenType::CloseBrace&&depth>0)--depth;if(k==TokenType::Semicolon&&depth==0)break;value+=t[p++].text;}if(p<end&&t[p].type==TokenType::Semicolon)++p;value=trim(value);bool important=false;auto bang=value.rfind('!');if(bang!=std::string::npos&&lower(trim(value.substr(bang+1)))=="important"){important=true;value=trim(value.substr(0,bang));}if(!prop.empty()&&!value.empty())out.push_back({prop,value,important});}return out;}
bool compound(const std::vector<Token>&t,std::size_t&p,std::size_t end,SimpleSelector&s){bool used=false;if(p<end&&t[p].type==TokenType::Ident){s.tag=lower(t[p++].text);used=true;}else if(p<end&&t[p].type==TokenType::Delim&&t[p].text=="*"){s.tag="*";++p;used=true;}while(p<end){if(t[p].type==TokenType::Hash){s.id=t[p++].text.substr(1);used=true;}else if(t[p].type==TokenType::Dot){++p;if(p>=end||t[p].type!=TokenType::Ident)return false;s.classes.push_back(t[p++].text);used=true;}else break;}return used;}
std::vector<Selector> selectorList(const std::vector<Token>&t,std::size_t p,std::size_t end){std::vector<Selector>out;while(p<end){while(p<end&&t[p].type==TokenType::Whitespace)++p;Selector s;SimpleSelector first;if(!compound(t,p,end,first)){while(p<end&&t[p].type!=TokenType::Comma)++p;if(p<end)++p;continue;}s.parts.push_back(std::move(first));bool valid=true;while(p<end){bool space=false;while(p<end&&t[p].type==TokenType::Whitespace){space=true;++p;}if(p>=end||t[p].type==TokenType::Comma)break;Combinator comb=Combinator::Descendant;if(t[p].type==TokenType::Greater){comb=Combinator::Child;++p;while(p<end&&t[p].type==TokenType::Whitespace)++p;}else if(!space){valid=false;break;}SimpleSelector next;if(!compound(t,p,end,next)){valid=false;break;}s.combinators.push_back(comb);s.parts.push_back(std::move(next));}if(valid)out.push_back(std::move(s));while(p<end&&t[p].type!=TokenType::Comma)++p;if(p<end)++p;}return out;}
struct Winner{std::string value;bool important=false;unsigned specificity=0;std::size_t order=0;bool set=false;};
void apply(std::unordered_map<std::string,Winner>&w,const Declaration&d,unsigned spec,std::size_t order){auto&c=w[d.property];auto incoming=std::tuple{d.important,spec,order};auto existing=std::tuple{c.important,c.specificity,c.order};if(!c.set||incoming>=existing)c={d.value,d.important,spec,order,true};}
}
std::vector<Token> Tokenizer::tokenize(std::string_view s)const{std::vector<Token>out;std::size_t p=0;while(p<s.size()){auto b=p;char c=s[p];if(ws(c)){while(p<s.size()&&ws(s[p]))++p;out.push_back({TokenType::Whitespace,std::string(s.substr(b,p-b)),b});continue;}if(c=='/'&&p+1<s.size()&&s[p+1]=='*'){auto e=s.find("*/",p+2);p=e==s.npos?s.size():e+2;out.push_back({TokenType::Whitespace," ",b});continue;}if(c=='"'||c=='\''){char q=c;++p;std::string v;while(p<s.size()&&s[p]!=q){if(s[p]=='\\'&&p+1<s.size())++p;v.push_back(s[p++]);}if(p<s.size())++p;out.push_back({TokenType::String,std::string(1,q)+v+q,b});continue;}if(c=='#'&&p+1<s.size()&&nameChar(s[p+1])){++p;auto x=p;while(p<s.size()&&nameChar(s[p]))++p;out.push_back({TokenType::Hash,"#"+std::string(s.substr(x,p-x)),b});continue;}if(nameStart(c)||(c=='-'&&p+1<s.size()&&nameChar(s[p+1]))){++p;while(p<s.size()&&nameChar(s[p]))++p;out.push_back({TokenType::Ident,std::string(s.substr(b,p-b)),b});continue;}++p;TokenType k=TokenType::Delim;switch(c){case '.':k=TokenType::Dot;break;case ':':k=TokenType::Colon;break;case ',':k=TokenType::Comma;break;case '>':k=TokenType::Greater;break;case '{':k=TokenType::OpenBrace;break;case '}':k=TokenType::CloseBrace;break;case ';':k=TokenType::Semicolon;break;case '!':k=TokenType::Bang;break;default:break;}out.push_back({k,std::string(1,c),b});}out.push_back({TokenType::End,{},s.size()});return out;}
bool Selector::matches(const dom::Element&e)const{return !parts.empty()&&matchAt(*this,parts.size()-1,e);}
unsigned Selector::specificity()const noexcept{unsigned ids=0,classes=0,tags=0;for(auto&p:parts){if(!p.id.empty())++ids;classes+=unsigned(p.classes.size());if(!p.tag.empty()&&p.tag!="*")++tags;}return ids*10000u+classes*100u+tags;}
StyleSheet Parser::parse(std::string_view s)const{auto t=Tokenizer{}.tokenize(s);StyleSheet sheet;std::size_t p=0,order=0;while(p<t.size()&&t[p].type!=TokenType::End){while(p<t.size()&&(t[p].type==TokenType::Whitespace||t[p].type==TokenType::Semicolon))++p;if(p>=t.size()||t[p].type==TokenType::End)break;auto sb=p;while(p<t.size()&&t[p].type!=TokenType::OpenBrace&&t[p].type!=TokenType::End)++p;if(p>=t.size()||t[p].type!=TokenType::OpenBrace)break;auto se=p++;auto db=p;while(p<t.size()&&t[p].type!=TokenType::CloseBrace&&t[p].type!=TokenType::End)++p;auto de=p;if(p<t.size()&&t[p].type==TokenType::CloseBrace)++p;Rule r;r.selectors=selectorList(t,sb,se);r.declarations=declarations(t,db,de);r.source_order=order++;if(!r.selectors.empty()&&!r.declarations.empty())sheet.rules_.push_back(std::move(r));}return sheet;}
const std::string* ComputedStyle::get(std::string_view p)const noexcept{auto i=properties_.find(std::string(p));return i==properties_.end()?nullptr:&i->second;}
bool ComputedStyle::contains(std::string_view p)const noexcept{return get(p)!=nullptr;}
ComputedStyle StyleResolver::compute(const dom::Element&e,const std::vector<const StyleSheet*>&sheets)const{std::unordered_map<std::string,Winner>w;std::size_t order=0;for(auto*sheet:sheets){if(!sheet)continue;for(auto&r:sheet->rules()){bool matched=false;unsigned spec=0;for(auto&s:r.selectors)if(s.matches(e)){matched=true;spec=std::max(spec,s.specificity());}if(matched)for(auto&d:r.declarations)apply(w,d,spec,order);++order;}}if(auto*style=e.getAttribute("style")){auto inlineSheet=Parser{}.parse(std::string("*{")+*style+"}");for(auto&r:inlineSheet.rules())for(auto&d:r.declarations)apply(w,d,1000000u,order++);}ComputedStyle result;for(auto&[k,v]:w)if(v.set)result.properties_.emplace(k,std::move(v.value));return result;}
std::unordered_map<const dom::Element*,ComputedStyle> StyleResolver::computeTree(const dom::Document&d,const std::vector<const StyleSheet*>&sheets)const{std::unordered_map<const dom::Element*,ComputedStyle>out;for(auto*e:d.getElementsByTagName("*"))out.emplace(e,compute(*e,sheets));return out;}
}
